    private function created(string $entity): array { $id=(string)$this->db->connection()->lastInsertId();$this->audit->record($entity,'created',$id);return ['id'=>$id]; }
    private function activeUser(mixed $id): array { $r=$this->row('users','user_id',$id); if($r['status']!=='ACTIVE')throw HttpException::unprocessable('Account must be active.');return $r; }
