    public function list(string $resource): array {
        $queries=[
            'dispatch'=>'SELECT * FROM dispatch_jobs WHERE company_id=:company ORDER BY dispatch_id DESC LIMIT 500',
            'lone-workers'=>'SELECT plan_id,shift_assignment_id,user_id,interval_minutes,next_due_at,ends_at,last_checkin_at,closed_at FROM lone_worker_plans WHERE company_id=:company ORDER BY plan_id DESC LIMIT 500',
            'gate'=>'SELECT * FROM gate_register WHERE company_id=:company ORDER BY gate_id DESC LIMIT 500',
            'rates'=>'SELECT * FROM contract_hourly_rates WHERE company_id=:company ORDER BY effective_from DESC LIMIT 500',
            'invoices'=>'SELECT invoice_id,contract_id,site_id,date_from,date_to,currency,subtotal_minor,state,created_at FROM invoice_drafts WHERE company_id=:company ORDER BY invoice_id DESC LIMIT 500',
            'signals'=>'SELECT * FROM operational_signals WHERE company_id=:company ORDER BY signal_id DESC LIMIT 500',
            'relief-history'=>'SELECT * FROM shift_relief_history WHERE company_id=:company ORDER BY relief_id DESC LIMIT 500',
