    public function createDispatch(array $input): array { return $this->atomic(function()use($input){
        $this->fields($input,['incident_id','responder_user_id','response_due_at']);$incident=$this->row('incidents','incident_id',$input['incident_id']??null);$responder=$this->activeUser($input['responder_user_id']??null);$due=$this->at($input['response_due_at']??null);
        if(!empty($incident['deleted_at'])||in_array($incident['status'],['CLOSED','RESOLVED','CANCELLED'],true)||$due<=gmdate('Y-m-d H:i:s')||strtotime($due.' UTC')>time()+86400)throw HttpException::unprocessable('Choose an open incident and a response deadline within 24 hours.');
        if($this->db->fetch("SELECT dispatch_id FROM dispatch_jobs WHERE company_id=:company AND incident_id=:incident AND state NOT IN ('CLOSED','CANCELLED')",['company'=>$this->company(),'incident'=>$incident['incident_id']]))throw HttpException::conflict('Incident already has an active dispatch.');
        $this->db->execute("INSERT INTO dispatch_jobs(company_id,incident_id,responder_user_id,state,response_due_at,created_at) VALUES(:company,:incident,:responder,'ASSIGNED',:due,:now)",['company'=>$this->company(),'incident'=>$incident['incident_id'],'responder'=>$responder['user_id'],'due'=>$due,'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('dispatch');
    }); }
    public function dispatchAction(string $id,string $action,array $input,bool $self=false): array {return $this->atomic(function()use($id,$action,$input,$self){
        $this->fields($input,['expected_revision','resolution']);$job=$this->row('dispatch_jobs','dispatch_id',$id);
        if($self&&((string)$job['responder_user_id']!==$this->actor()||!in_array($action,['accept','arrive'],true)))throw HttpException::notFound();
        if($this->integer($input['expected_revision']??null)!==(int)$job['revision'])throw HttpException::conflict('Dispatch changed. Refresh before updating.');
        $states=['accept'=>['ASSIGNED','ACCEPTED','accepted_at'],'arrive'=>['ACCEPTED','ARRIVED','arrived_at'],'close'=>['ARRIVED','CLOSED','closed_at']];
        if($action==='cancel'){if(in_array($job['state'],['CLOSED','CANCELLED'],true))throw HttpException::conflict('Dispatch already ended.');$target='CANCELLED';$column='closed_at';}
        else {if(!isset($states[$action]))throw HttpException::notFound();[$from,$target,$column]=$states[$action];if($job['state']!==$from)throw HttpException::conflict('Invalid dispatch transition.');}
        $resolution=in_array($action,['close','cancel'],true)?$this->text($input['resolution']??null,1000):null;
        $this->db->execute("UPDATE dispatch_jobs SET state=:state,$column=:now,resolution=:resolution,revision=revision+1 WHERE company_id=:company AND dispatch_id=:id",['state'=>$target,'now'=>gmdate('Y-m-d H:i:s'),'resolution'=>$resolution,'company'=>$this->company(),'id'=>$id]);$this->audit->record('dispatch',$action,$id);return ['state'=>$target,'revision'=>(int)$job['revision']+1];
    });}
    public function selfWorkspace(): array {
        $actor=$this->actor();return ['dispatch'=>$this->db->fetchAll("SELECT d.* FROM dispatch_jobs d WHERE d.company_id=:company AND d.responder_user_id=:actor AND d.state NOT IN ('CLOSED','CANCELLED') ORDER BY d.response_due_at LIMIT 100",['company'=>$this->company(),'actor'=>$actor]),'checkins'=>$this->db->fetchAll('SELECT plan_id,shift_assignment_id,next_due_at,ends_at,closed_at FROM lone_worker_plans WHERE company_id=:company AND user_id=:actor AND closed_at IS NULL ORDER BY next_due_at LIMIT 100',['company'=>$this->company(),'actor'=>$actor])];
    }
    public function createLonePlan(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['shift_assignment_id','user_id','interval_minutes']);$shift=$this->row('shift_assignments','shift_assignment_id',$input['shift_assignment_id']??null);$user=$this->activeUser($input['user_id']??null);$interval=$this->integer($input['interval_minutes']??null,1,240);
        if((string)$shift['employee_id']!==(string)$user['employee_id']||!empty($shift['deleted_at'])||!in_array($shift['assignment_status'],['ASSIGNED','CONFIRMED','IN_PROGRESS'],true)||$shift['shift_end_at']<=gmdate('Y-m-d H:i:s'))throw HttpException::unprocessable('Choose the active guard account for an upcoming or current assigned shift.');
        if($this->db->fetch('SELECT plan_id FROM lone_worker_plans WHERE company_id=:company AND shift_assignment_id=:shift',['company'=>$this->company(),'shift'=>$shift['shift_assignment_id']]))throw HttpException::conflict('Shift already has a check-in plan.');
        $code=bin2hex(random_bytes(4));$due=gmdate('Y-m-d H:i:s',max(time(),strtotime($shift['shift_start_at'].' UTC'))+$interval*60);
        $this->db->execute('INSERT INTO lone_worker_plans(company_id,shift_assignment_id,user_id,interval_minutes,next_due_at,ends_at,duress_hash) VALUES(:company,:shift,:user,:minutes,:due,:end,:hash)',['company'=>$this->company(),'shift'=>$shift['shift_assignment_id'],'user'=>$user['user_id'],'minutes'=>$interval,'due'=>$due,'end'=>$shift['shift_end_at'],'hash'=>password_hash($code,PASSWORD_DEFAULT)]);return $this->created('lone_worker_plan')+['duress_code'=>$code,'note'=>'Share privately with this guard. A duress submission appears as an ordinary check-in to the guard.'];
    });}
    public function checkin(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['code']);$plan=$this->row('lone_worker_plans','plan_id',$id);if((string)$plan['user_id']!==$this->actor())throw HttpException::notFound();
