        $shift=$this->row('shift_assignments','shift_assignment_id',$plan['shift_assignment_id']);if($now<$shift['shift_start_at']||!empty($shift['deleted_at'])||$shift['assignment_status']==='CANCELLED')throw HttpException::conflict('Check-in shift is not active.');
