        $due=gmdate('Y-m-d H:i:s',time()+(int)$plan['interval_minutes']*60);$this->db->execute('UPDATE lone_worker_plans SET last_checkin_at=:now,next_due_at=:due WHERE company_id=:company AND plan_id=:id',['now'=>$now,'due'=>$due,'company'=>$this->company(),'id'=>$id]);
