    });}
    public function closePlan(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['reason']);$this->row('lone_worker_plans','plan_id',$id);$reason=$this->text($input['reason']??null);$this->db->execute('UPDATE lone_worker_plans SET closed_at=:now WHERE company_id=:company AND plan_id=:id AND closed_at IS NULL',['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('lone_worker_plan','closed',$id,[],[],['reason'=>$reason]);return ['closed'=>true];});}
    public function createCoverage(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['post_id','starts_at','ends_at','required_guards']);$post=$this->row('posts','post_id',$input['post_id']??null);$this->site($post['site_id']);if($post['status']!=='ACTIVE'||!empty($post['deleted_at']))throw HttpException::unprocessable('Post is unavailable.');$start=$this->at($input['starts_at']??null);$end=$this->at($input['ends_at']??null);if($end<=$start||strtotime($end.' UTC')-strtotime($start.' UTC')>172800)throw HttpException::unprocessable('Coverage must last between zero and 48 hours.');
