        foreach($rows as&$r){$shifts=$this->db->fetchAll("SELECT employee_id,shift_start_at,shift_end_at FROM shift_assignments WHERE company_id=:company AND post_id=:post AND deleted_at IS NULL AND assignment_status IN ('ASSIGNED','CONFIRMED','IN_PROGRESS','COMPLETED') AND shift_start_at<:end AND shift_end_at>:start",['company'=>$this->company(),'post'=>$r['post_id'],'start'=>$r['starts_at'],'end'=>$r['ends_at']]);
            $points=[$r['starts_at'],$r['ends_at']];foreach($shifts as$s){$points[]=max($r['starts_at'],$s['shift_start_at']);$points[]=min($r['ends_at'],$s['shift_end_at']);}sort($points);$points=array_values(array_unique($points));$minimum=PHP_INT_MAX;
