    }
    public function cancelCoverage(string $id): array {return $this->atomic(function()use($id){$this->row('coverage_requirements','coverage_id',$id);$this->db->execute('UPDATE coverage_requirements SET cancelled_at=:now WHERE company_id=:company AND coverage_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('coverage','cancelled',$id);return ['cancelled'=>true];});}
    public function relief(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['expected_employee_id','replacement_employee_id','reason']);$shift=$this->row('shift_assignments','shift_assignment_id',$id);$employee=$this->row('employees','employee_id',$input['replacement_employee_id']??null);$reason=$this->text($input['reason']??null);
        if($this->integer($input['expected_employee_id']??null)!==(int)$shift['employee_id'])throw HttpException::conflict('Shift changed. Refresh first.');
