        if($this->db->fetch("SELECT shift_assignment_id FROM shift_assignments WHERE company_id=:company AND employee_id=:employee AND deleted_at IS NULL AND assignment_status NOT IN ('CANCELLED','MISSED') AND shift_start_at<:end AND shift_end_at>:start",['company'=>$this->company(),'employee'=>$employee['employee_id'],'start'=>$shift['shift_start_at'],'end'=>$shift['shift_end_at']]))throw HttpException::conflict('Replacement already has an overlapping shift.');
        $this->db->execute('INSERT INTO shift_relief_history(company_id,shift_assignment_id,previous_employee_id,replacement_employee_id,reason,changed_by_user_id,changed_at) VALUES(:company,:shift,:previous,:replacement,:reason,:actor,:now)',['company'=>$this->company(),'shift'=>$id,'previous'=>$shift['employee_id'],'replacement'=>$employee['employee_id'],'reason'=>$reason,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);
        $this->db->execute("UPDATE shift_assignments SET employee_id=:employee,assignment_status='ASSIGNED' WHERE company_id=:company AND shift_assignment_id=:id",['employee'=>$employee['employee_id'],'company'=>$this->company(),'id'=>$id]);$this->audit->record('shift','relief_assigned',$id);return ['assigned'=>true];
