    public function gate(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['operation_uuid','site_id','visitor_name','vehicle_registration','purpose','direction','authorization','occurred_at']);$uuid=$input['operation_uuid']??null;if(!is_string($uuid)||!preg_match('/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/Di',$uuid))throw HttpException::unprocessable('A stable operation UUID is required.');$uuid=strtolower($uuid);
