        $this->db->execute('INSERT INTO gate_register(company_id,recorded_by_user_id,operation_uuid,request_hash,site_id,visitor_name,vehicle_registration,purpose,direction,authorization,occurred_at,received_at) VALUES(:company,:actor,:uuid,:hash,:site,:name,:vehicle,:purpose,:direction,:authorization,:at,:now)',$keys+['hash'=>$hash,'site'=>$site['site_id'],'name'=>$this->text($input['visitor_name']??null,150),'vehicle'=>empty($input['vehicle_registration'])?null:strtoupper($this->text($input['vehicle_registration'],30)),'purpose'=>$this->text($input['purpose']??null),'direction'=>$input['direction'],'authorization'=>$input['authorization'],'at'=>$at,'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('gate_capture')+['received'=>true];
    });}
    public function rate(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['contract_id','site_id','hourly_minor','currency','effective_from']);$contract=$this->row('contracts','contract_id',$input['contract_id']??null);$site=$this->site($input['site_id']??null);if(!empty($contract['deleted_at'])||$contract['status']!=='ACTIVE'||(string)($site['contract_id']??'')!==(string)$contract['contract_id'])throw HttpException::unprocessable('Choose an active contract attached to this site.');$currency=$this->text($input['currency']??null,3);if(!preg_match('/^[A-Z]{3}$/D',$currency))throw HttpException::unprocessable('Use a three-letter currency code.');
