        $this->db->execute('INSERT INTO contract_hourly_rates(company_id,contract_id,site_id,hourly_minor,currency,effective_from) VALUES(:company,:contract,:site,:rate,:currency,:date)',['company'=>$this->company(),'contract'=>$contract['contract_id'],'site'=>$site['site_id'],'rate'=>$this->integer($input['hourly_minor']??null,1,100000000),'currency'=>$currency,'date'=>$date]);return $this->created('contract_rate');
    });}
    public function invoice(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['contract_id','site_id','date_from','date_to']);$contract=$this->row('contracts','contract_id',$input['contract_id']??null);$site=$this->site($input['site_id']??null);if((string)($site['contract_id']??'')!==(string)$contract['contract_id']||!empty($contract['deleted_at']))throw HttpException::unprocessable('Contract does not cover this site.');
