            if($currency!==null&&$currency!==$rate['currency'])throw HttpException::unprocessable('Split invoices when currency changes.');$currency=$rate['currency'];$seconds=strtotime($row['clock_out_at'].' UTC')-strtotime($row['clock_in_at'].' UTC');$amount=intdiv($seconds*(int)$rate['hourly_minor']+1800,3600);$sum+=$amount;$lines[]=['attendance_id'=>$row['attendance_id'],'record_hash'=>FieldOperationsService::attendanceHash($row),'date'=>$row['shift_date'],'seconds'=>$seconds,'rate_id'=>$rate['rate_id'],'hourly_minor'=>$rate['hourly_minor'],'amount_minor'=>$amount];
        }
