    });}
    public function invoiceDetail(string $id): array {
        $row=$this->row('invoice_drafts','invoice_id',$id);$lines=json_decode($row['lines_json'],true,512,JSON_THROW_ON_ERROR);$stale=false;
        foreach($lines as$line){$a=$this->db->fetch('SELECT attendance_id,employee_id,site_id,shift_date,clock_in_at,clock_out_at FROM attendance WHERE company_id=:company AND attendance_id=:id AND deleted_at IS NULL',['company'=>$this->company(),'id'=>$line['attendance_id']]);if(!$a||!hash_equals($line['record_hash'],FieldOperationsService::attendanceHash($a)))$stale=true;}
        unset($row['lines_json']);return $row+['lines'=>$lines,'attendance_changed'=>$stale,'note'=>'Draft only. Review current attendance, breaks, tax, overtime and contract terms before invoicing.'];
    }
    public function voidInvoice(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['reason']);$row=$this->row('invoice_drafts','invoice_id',$id);if($row['state']!=='DRAFT')throw HttpException::conflict('Only an active draft can be voided.');$reason=$this->text($input['reason']??null);
        $this->db->execute("UPDATE invoice_drafts SET state='VOID' WHERE company_id=:company AND invoice_id=:id",['company'=>$this->company(),'id'=>$id]);$this->audit->record('invoice_draft','voided',$id,[],[],['reason'=>$reason]);return ['voided'=>true];
    });}
    private function signal(string $key,string $type,?int $record,string $message): void {
        if($this->db->fetch('SELECT signal_id FROM operational_signals WHERE company_id=:company AND signal_key=:key',['company'=>$this->company(),'key'=>$key]))return;
        $this->db->execute('INSERT INTO operational_signals(company_id,signal_key,signal_type,record_id,message,created_at) VALUES(:company,:key,:type,:record,:message,:now)',['company'=>$this->company(),'key'=>$key,'type'=>$type,'record'=>$record,'message'=>$message,'now'=>gmdate('Y-m-d H:i:s')]);
    }
    public function acknowledge(string $id): array {return $this->atomic(function()use($id){$this->row('operational_signals','signal_id',$id);$this->db->execute('UPDATE operational_signals SET acknowledged_at=:now,acknowledged_by_user_id=:actor WHERE company_id=:company AND signal_id=:id AND acknowledged_at IS NULL',['now'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor(),'company'=>$this->company(),'id'=>$id]);$this->audit->record('operational_signal','acknowledged',$id);return ['acknowledged'=>true];});}
    /** Scheduled every minute. Missing check-ins remain visible even after the shift ends. */
    public function tick(): array {return $this->atomic(function(){
        $now=gmdate('Y-m-d H:i:s');foreach($this->db->fetchAll("SELECT dispatch_id FROM dispatch_jobs WHERE company_id=:company AND state IN ('ASSIGNED','ACCEPTED') AND response_due_at<:now",['company'=>$this->company(),'now'=>$now])as$r)$this->signal('dispatch:'.$r['dispatch_id'],'RESPONSE_OVERDUE',(int)$r['dispatch_id'],'Responder has not arrived by the response deadline. Contact the responder and escalate.');
        foreach($this->db->fetchAll('SELECT plan_id,next_due_at FROM lone_worker_plans WHERE company_id=:company AND closed_at IS NULL AND next_due_at<:now AND next_due_at<=ends_at',['company'=>$this->company(),'now'=>$now])as$r)$this->signal('checkin:'.$r['plan_id'].':'.$r['next_due_at'],'CHECK_IN_MISSED',(int)$r['plan_id'],'A scheduled lone-worker check-in was missed. Contact the guard and follow the emergency procedure.');
        $this->db->execute("INSERT INTO worker_runs(company_id,worker_name,started_at,finished_at,state,summary) VALUES(:company,'control-room',:start,:end,'OK','Dispatch and check-in deadlines evaluated.')",['company'=>$this->company(),'start'=>$now,'end'=>gmdate('Y-m-d H:i:s')]);return ['evaluated_at'=>$now,'unacknowledged_signals'=>(int)$this->db->fetch('SELECT COUNT(*) AS total FROM operational_signals WHERE company_id=:company AND acknowledged_at IS NULL',['company'=>$this->company()])['total']];
    });}
    public function recordWorkerFailure(string $worker): void { $this->db->execute("INSERT INTO worker_runs(company_id,worker_name,started_at,finished_at,state,summary) VALUES(:company,:worker,:start,:end,'FAILED','Worker failed; inspect restricted server logs.')",['company'=>$this->company(),'worker'=>$worker,'start'=>gmdate('Y-m-d H:i:s'),'end'=>gmdate('Y-m-d H:i:s')]); }
    public function backup(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['backup_reference','backed_up_at','restored_at']);$at=$this->at($input['backed_up_at']??null);$restore=empty($input['restored_at'])?null:$this->at($input['restored_at']);$now=gmdate('Y-m-d H:i:s');if($at>$now||($restore!==null&&($restore<$at||$restore>$now)))throw HttpException::unprocessable('Backup and restoration dates must be in the past and in order.');$this->db->execute('INSERT INTO backup_checks(company_id,backup_reference,backed_up_at,restored_at,checked_by_user_id,recorded_at) VALUES(:company,:reference,:at,:restore,:actor,:now)',['company'=>$this->company(),'reference'=>$this->text($input['backup_reference']??null,150),'at'=>$at,'restore'=>$restore,'actor'=>$this->actor(),'now'=>$now]);return $this->created('backup_check')+['note'=>'Operator supplied evidence; Sentinel has not performed a backup or restoration.'];
    });}
    public function healthReport(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['installation_id','battery_percent','version_code']);$uuid=$input['installation_id']??null;if(!is_string($uuid)||!preg_match('/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/Di',$uuid))throw HttpException::unprocessable('Invalid installation ID.');$keys=['company'=>$this->company(),'actor'=>$this->actor(),'installation'=>strtolower($uuid)];$battery=$this->integer($input['battery_percent']??null,0,100);$version=$this->integer($input['version_code']??null);
        $this->db->execute('DELETE FROM phone_health WHERE company_id=:company AND user_id=:actor AND installation_id=:installation',$keys);$this->db->execute('INSERT INTO phone_health(company_id,user_id,installation_id,battery_percent,version_code,received_at) VALUES(:company,:actor,:installation,:battery,:version,:now)',$keys+['battery'=>$battery,'version'=>$version,'now'=>gmdate('Y-m-d H:i:s')]);return ['received'=>true];
    });}
    public function deviceHealth(int $minimumVersion): array {
        $phones=$this->db->fetchAll('SELECT * FROM phone_health WHERE company_id=:company ORDER BY received_at LIMIT 500',['company'=>$this->company()]);foreach($phones as&$p){$p['low_battery']=(int)$p['battery_percent']<=20;$p['outdated']=(int)$p['version_code']<$minimumVersion;$p['missing_contact']=$p['received_at']<gmdate('Y-m-d H:i:s',time()-900);}unset($p);
        $managed=$this->db->fetchAll('SELECT managed_device_id,device_name,revision,reported_revision,reported_state,last_seen_at,policy_json FROM managed_android WHERE company_id=:company ORDER BY managed_device_id LIMIT 500',['company'=>$this->company()]);foreach($managed as&$m){$policy=json_decode($m['policy_json'],true);$m['missing_contact']=empty($m['last_seen_at'])||$m['last_seen_at']<gmdate('Y-m-d H:i:s',time()-900);$m['policy_needs_attention']=(int)$m['revision']!==(int)$m['reported_revision']||($policy['enabled']??false)&&$m['reported_state']!=='APPLIED';unset($m['policy_json']);}unset($m);return ['minimum_version_code'=>$minimumVersion,'phones'=>$phones,'managed'=>$managed,'note'=>'Device-reported observations; no independent attestation. No report means battery and version are unknown.'];
    }
    public function readiness(): array {
        $workers=[];foreach(['control-room','escalations','client-reports','operations-hub','business-operations','backups']as$name){$last=$this->db->fetch('SELECT worker_name,finished_at,state,summary FROM worker_runs WHERE company_id=:company AND worker_name=:name ORDER BY run_id DESC LIMIT 1',['company'=>$this->company(),'name'=>$name]);$workers[]=['worker'=>$name,'state'=>$last===null?'UNKNOWN':($last['state']==='FAILED'?'FAILED':($last['finished_at']<gmdate('Y-m-d H:i:s',time()-300)?'STALE':'OK')),'last_run'=>$last];}
        $backup=$this->db->fetch('SELECT backup_reference,backed_up_at,restored_at,checked_by_user_id,recorded_at FROM backup_checks WHERE company_id=:company ORDER BY backed_up_at DESC,backup_check_id DESC LIMIT 1',['company'=>$this->company()]);
        return ['generated_at'=>gmdate('Y-m-d H:i:s'),'workers'=>$workers,'backup'=>['state'=>$backup===null?'UNKNOWN':($backup['backed_up_at']<gmdate('Y-m-d H:i:s',time()-86400)?'STALE':'RECORDED'),'evidence'=>$backup,'note'=>'Operator supplied evidence. Validate the backup destination and rehearse restoration separately.'],'unresolved_signals'=>$this->db->fetchAll('SELECT signal_id,signal_type,record_id,message,created_at FROM operational_signals WHERE company_id=:company AND acknowledged_at IS NULL ORDER BY created_at LIMIT 500',['company'=>$this->company()]),'client_report_email_states'=>$this->db->fetchAll('SELECT state,COUNT(*) AS total FROM client_report_outbox WHERE company_id=:company GROUP BY state',['company'=>$this->company()]),'escalation_delivery'=>'IN_APP_ONLY','note'=>'Acknowledging a signal records receipt; it does not resolve an incident. Check missing radios, providers and server infrastructure separately.'];
    }
}
